"use client";
import { useId, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { useContinuity } from "./use-continuity";
import "./roc.css";
export interface SourceItem { id: string; title: string; kind: string; content: ReactNode; color?: string }
/** Each source owns one mounted subtree through pile, spread and focused detail. */
export function SourceStack({ items, color, duration }: { items: SourceItem[]; color?: string; duration?: number }) {
  const [spread, setSpread] = useState(false), [selected, setSelected] = useState<string | null>(null);
  const { root, change } = useContinuity(), id = useId(), toggle = useRef<HTMLButtonElement>(null);
  const select = (key: string | null) => change(() => { setSelected(key); if (key) setSpread(true); });
  return <div ref={root} style={{ "--roc-duration": duration ? `${duration}ms` : undefined } as CSSProperties} className={`roc-sources ${spread ? "is-spread" : ""} ${selected ? "has-selection" : ""}`} onKeyDown={e => { if (e.key === "Escape" && (spread || selected)) { e.stopPropagation(); if (!selected) change(() => setSpread(false)); else select(null); toggle.current?.focus(); } }}>
    <button ref={toggle} className="roc-text-button roc-source-toggle" aria-expanded={spread} aria-controls={id} onClick={() => change(() => { setSpread(!spread); setSelected(null); })}>{spread ? "Gather sources" : "Unfold sources"} <span>↗</span></button>
    <div id={id} className="roc-source-items" inert={!spread} aria-hidden={!spread}>
      {items.map((item, index) => <article key={item.id} data-roc-item className={`roc-source ${selected === item.id ? "is-selected" : ""}`} style={{ background: color ? `color-mix(in srgb, ${color} ${12 + index * 12}%, white)` : item.color, left: selected === item.id ? "50%" : spread ? `${items.length <= 1 ? 50 : 16 + index / (items.length - 1) * 68}%` : "50%", top: selected === item.id ? 0 : spread ? 35 : 30 + index * 6, transform: `translateX(-50%) rotate(${spread ? 0 : (index - (items.length - 1) / 2) * 7}deg)`, zIndex: selected === item.id ? 10 : index + 1 }} inert={!!selected && selected !== item.id}>
        <span className="roc-eyebrow">{item.kind}</span><h3>{item.title}</h3>
        <div className="roc-source-content">{item.content}</div>
        <button className="roc-text-button" aria-pressed={selected === item.id} onClick={() => select(selected === item.id ? null : item.id)}>{selected === item.id ? "Return ↙" : "Inspect ↗"}</button>
      </article>)}
    </div>
  </div>;
}

"use client";
import { useCallback, useLayoutEffect, useRef } from "react";

/** Measure before changing layout; retain actual nodes and retarget from their visible pose.
 * Layout retargeting preserves the current measured pose; release velocity is not preserved.
 */
export function useContinuity(duration = 480) {
  const root = useRef<HTMLDivElement>(null);
  const before = useRef(new Map<HTMLElement, DOMRect>());
  const animations = useRef(new Map<HTMLElement, Animation>());
  const change = useCallback((update: () => void) => {
    before.current.clear();
    root.current?.querySelectorAll<HTMLElement>("[data-roc-item]").forEach(node => {
      before.current.set(node, node.getBoundingClientRect());
    });
    update();
  }, []);
  useLayoutEffect(() => {
    if (!before.current.size) return;
    const configured = Number.parseFloat(root.current ? getComputedStyle(root.current).getPropertyValue("--roc-duration") : "");
    const timing = Number.isFinite(configured) ? configured : duration;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
    for (const [node, old] of before.current) {
      animations.current.get(node)?.cancel();
      if (!node.isConnected || reduced) continue;
      const next = node.getBoundingClientRect();
      if (!next.width || !next.height) continue;
      const scale = node.dataset.rocScale !== "false";
      const animation = node.animate([
        { translate: `${old.x - next.x}px ${old.y - next.y}px`, scale: scale ? `${old.width / next.width} ${old.height / next.height}` : "1" },
        { translate: "0px 0px", scale: "1" },
      ], { duration: timing, easing: "cubic-bezier(.22,.8,.25,1)" });
      animations.current.set(node, animation);
      void animation.finished.then(() => {
        if (animations.current.get(node) === animation) animations.current.delete(node);
      }).catch(() => {});
    }
    before.current.clear();
  });
  useLayoutEffect(() => () => { animations.current.forEach(a => a.cancel()); }, []);
  return { root, change };
}

/* ROC owns only these prefixed classes. Override tokens at your component boundary. */
.roc-expand,.roc-folder,.roc-sources,.roc-lanes,.roc-tabs{--roc-paper:#fffcf6;--roc-ink:#2c302c;--roc-line:#d8dcd4;--roc-muted:#757b72;--roc-accent:#476946;color:var(--roc-ink);font-family:inherit;box-sizing:border-box}
.roc-expand *,.roc-folder *,.roc-sources *,.roc-lanes *,.roc-tabs *{box-sizing:border-box}
.roc-expand button,.roc-folder button,.roc-sources button,.roc-lanes button,.roc-tabs button{font:inherit;color:inherit;cursor:pointer}
.roc-expand button:focus-visible,.roc-folder button:focus-visible,.roc-sources button:focus-visible,.roc-lanes button:focus-visible,.roc-tabs button:focus-visible{outline:2px solid var(--roc-accent);outline-offset:5px}
.roc-eyebrow{font:10px/1.4 ui-monospace,monospace;letter-spacing:.12em;color:var(--roc-muted)}
.roc-text-button{border:0;background:none;padding:9px 0;font-size:12px!important;text-align:left;display:inline-flex;gap:20px;align-items:center}
.roc-expand{width:100%;min-height:280px;display:flex;align-items:center;justify-content:center;padding:24px}
.roc-paper{transform-origin:0 0;background:var(--roc-paper);border:1px solid #e1dfd4;border-radius:3px;width:250px;padding:27px;box-shadow:0 3px 4px #252d2110,0 12px 32px #252d2108}
.roc-paper h3{font:normal 26px/1.1 Georgia,serif;margin:17px 0 12px;letter-spacing:-.035em}
.roc-summary{font-size:12px;line-height:1.65;color:var(--roc-muted);max-width:240px}
.roc-paper-body{height:0;overflow:hidden;visibility:hidden;font-size:14px;line-height:1.75}
.roc-expand.is-open .roc-paper{width:min(100%,480px)}
.roc-expand.is-open .roc-paper-body{height:auto;visibility:visible;margin:22px 0 14px}
.roc-paper-body textarea{width:100%;resize:vertical;border:1px solid var(--roc-line);border-radius:5px;padding:10px;background:transparent;color:inherit;font:inherit;min-height:85px}
.roc-folder{height:330px;width:100%;max-width:560px;position:relative;isolation:isolate;margin:auto}
.roc-folder-back{position:absolute;left:50%;top:139px;width:224px;height:150px;transform:translateX(-50%);background:#b8bda2;border-radius:8px 18px 15px 15px;z-index:0}
.roc-folder-back:before{content:"";position:absolute;top:-13px;width:88px;height:25px;background:inherit;border-radius:9px 14px 0 0}
.roc-folder-items{position:absolute;inset:0;z-index:1}
.roc-folder-card{position:absolute;width:125px;height:155px;padding:16px;text-align:left;border:1px solid #d9d8cb;border-radius:4px;background:var(--roc-paper);box-shadow:0 4px 9px #2730200c;transform-origin:0 0;transition:transform .56s cubic-bezier(.22,.8,.25,1)}
.roc-folder-card strong{display:block;font:normal 20px/1.15 Georgia,serif;margin-top:18px}
.roc-card-content{display:block;margin-top:16px;font-size:10px;line-height:1.5;color:var(--roc-muted)}
.roc-folder-toggle{position:absolute;z-index:2;left:50%;top:169px;width:238px;height:128px;transform:translateX(-50%);border:1px solid #aab293;background:#c9cfb5;border-radius:7px 7px 15px 15px;text-align:left;padding:25px 21px;box-shadow:0 8px 14px #35402212;transform-origin:bottom;transition:transform .56s cubic-bezier(.22,.8,.25,1),background .3s}
.roc-folder-toggle>span:first-child{display:block;font-size:15px;margin-bottom:25px}.roc-folder-toggle>span:last-child{display:flex;justify-content:space-between;font-size:11px;color:#5d684d}.roc-folder-toggle b{font-size:18px;font-weight:400}
.roc-folder.is-open .roc-folder-toggle{transform:translateX(-50%) perspective(700px) rotateX(-18deg);background:#d7dcc6}
.roc-sources{position:relative;height:340px;width:100%;max-width:580px;margin:auto}
.roc-source-toggle{position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:nowrap;z-index:12}
.roc-source-items{position:absolute;inset:55px 0 0}
.roc-source{position:absolute;width:146px;min-height:205px;border:1px solid #dbddd4;padding:20px 16px;background:var(--roc-paper);border-radius:5px;box-shadow:0 5px 14px #1e27100b;transform-origin:0 0;transition:transform .48s cubic-bezier(.22,.8,.25,1),opacity .3s}
.roc-source h3{font:normal 20px/1.15 Georgia,serif;letter-spacing:-.02em;margin:17px 0 12px}
.roc-source-content{font-size:11px;line-height:1.6;max-height:67px;overflow:hidden}
.roc-source-content input{width:100%;min-width:0;padding:6px;border:1px solid #bac2b0;background:transparent;font:inherit;border-radius:3px}
.roc-source.is-selected{width:min(80%,330px);min-height:225px}.roc-source.is-selected .roc-source-content{max-height:none}
.roc-sources.has-selection .roc-source:not(.is-selected){opacity:.2}
.roc-lanes{display:flex;width:100%;min-width:250px;overflow:hidden;border:1px solid var(--roc-line);border-radius:8px;background:#fcfdf9}
.roc-lane{position:relative;flex:0 0 45px;min-width:0;border-right:1px solid var(--roc-line);transition:flex-basis .48s cubic-bezier(.22,.8,.25,1),flex-grow .48s cubic-bezier(.22,.8,.25,1);overflow:hidden}.roc-lane:last-child{border:0}.roc-lane.is-focused{flex:1 1 0}
.roc-lane-heading{height:44px;width:100%;display:flex;align-items:center;gap:10px;padding:0 16px;background:none;border:0;border-bottom:1px solid var(--roc-line);font-size:12px!important;text-align:left;white-space:nowrap}.roc-lane-dot,.roc-event-dot{flex:none;display:block;width:9px;height:9px;background:var(--lane-color);border-radius:2px}
.roc-lane-title,.roc-event-label{opacity:0;transition:opacity .18s}.is-focused .roc-lane-title,.is-focused .roc-event-label{opacity:1}
.roc-lane-events{position:relative}.roc-lane-event{position:absolute;left:0;right:0;height:38px;display:flex;align-items:center;gap:12px;text-align:left;border:0;background:none;padding:0 16px;overflow:hidden;white-space:nowrap;font-size:11px!important}.roc-lane-event:hover,.roc-lane-event.is-selected{background:#edf0e7}.roc-event-dot{width:12px;height:18px}.roc-event-label{white-space:nowrap}
.roc-tabs{position:relative;display:inline-flex;border:1px solid var(--roc-line);padding:4px;border-radius:9px;background:#f0f1eb;max-width:100%}
.roc-tabs button{position:relative;z-index:1;background:none;border:0;padding:11px 18px;font-size:12px;border-radius:5px;white-space:nowrap}.roc-tabs button[data-active=true]{color:#2c4227}
.roc-tab-marker{position:absolute;left:0;top:4px;bottom:4px;border-radius:5px;background:#fff;box-shadow:0 1px 4px #20282012;transition:transform .36s cubic-bezier(.22,.8,.25,1),width .36s cubic-bezier(.22,.8,.25,1)}
@media(max-width:480px){.roc-folder-card{width:94px;padding:12px;height:145px}.roc-folder-card strong{font-size:17px}.roc-folder-back{width:190px}.roc-folder-toggle{width:205px}.roc-source{width:105px;padding:12px}.roc-source h3{font-size:16px}.roc-tabs button{padding:10px 12px}.roc-expand{padding:20px 12px}}
@media(prefers-reduced-motion:reduce){.roc-folder *,.roc-sources *,.roc-lanes *,.roc-tabs *{transition:none!important;animation:none!important}}
/* Configurable surfaces. Geometry stays inside the same retained collection. */
.roc-folder{height:340px;max-width:500px;container-type:inline-size}
.roc-folder-back{left:50%;top:49%;width:210px;height:150px;background:color-mix(in srgb,var(--folder-color,#a8c6ee),#454d5c 13%);border:1px solid #ffffff50;box-shadow:inset 0 1px #ffffff70;transition:left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1)}
.roc-folder-back:before{width:80px;top:-14px;height:25px}
.roc-folder-card{width:118px;height:152px;padding:12px;border:1px solid #ffffff70;border-radius:9px;box-shadow:0 5px 14px #22222216;transform-origin:center;transition:left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),top var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),transform var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),box-shadow .2s}
.roc-folder-card:hover{box-shadow:0 13px 24px #22222220}.roc-folder-card strong{font-size:20px}.roc-card-content{margin-top:12px}
.roc-folder-toggle{left:50%;top:58%;width:228px;height:133px;padding:22px;border:1px solid #ffffff90;border-radius:9px 9px 19px 19px;transform:translateX(-50%);transform-origin:50% 100%;background:var(--folder-color,#a8c6ee);box-shadow:inset 0 1px 1px #ffffff70,0 14px 24px #2933420c;transition:transform var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),left var(--roc-duration,560ms) cubic-bezier(.22,.8,.25,1),background .25s}
.roc-folder-toggle>span:first-child{font-size:13px}.roc-folder-toggle>span:last-child{color:#273344a6}
.roc-folder[data-material=glass] .roc-folder-toggle{background:color-mix(in srgb,var(--folder-color,#a8c6ee) 67%,transparent);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px)}
.roc-folder.is-open .roc-folder-toggle{background:var(--folder-color,#a8c6ee);transform:translateX(-50%) perspective(650px) rotateX(-24deg)}
.roc-folder.is-open[data-material=glass] .roc-folder-toggle{background:color-mix(in srgb,var(--folder-color,#a8c6ee) 67%,transparent)}
.roc-folder[data-direction=right] .roc-folder-back,.roc-folder[data-direction=right] .roc-folder-toggle{left:28%;width:162px}
.roc-folder[data-direction=right] .roc-folder-toggle{transform-origin:0% 50%}
.roc-folder[data-direction=right].is-open .roc-folder-toggle{transform:translateX(-50%) perspective(650px) rotateY(-26deg)}
.roc-source{transition:transform var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1),opacity .3s}
.roc-lane{transition:flex-basis var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1),flex-grow var(--roc-duration,480ms) cubic-bezier(.22,.8,.25,1)}
.roc-tab-marker{transition:transform var(--roc-duration,360ms) cubic-bezier(.22,.8,.25,1),width var(--roc-duration,360ms) cubic-bezier(.22,.8,.25,1);background:var(--roc-marker,#fff)}
@container(max-width:350px){.roc-folder-card{width:94px;height:143px}.roc-folder-card strong{font-size:17px}.roc-folder-toggle{width:200px}.roc-folder-back{width:190px}.roc-folder[data-direction=right] .roc-folder-toggle,.roc-folder[data-direction=right] .roc-folder-back{width:132px}.roc-folder[data-direction=right] .roc-folder-toggle{padding:16px}}
@media(prefers-reduced-motion:reduce){.roc-folder *,.roc-source,.roc-lane,.roc-tab-marker{transition:none!important}}
